window.onload = function() {
setTimeout(function() {
const agent = window.navigator.userAgent;
console.log(agent);
if (agent.indexOf("APPWebview") != -1) {
    const header = document.querySelector('.l-header');
    const headersche = document.querySelector('.l-header__schedule-top');
    const footer = document.querySelector('.l-footer');
    const menu = document.querySelector('.p-menu-sp__container');
    const backlink = document.querySelector('.backlink'); 
    const thummenu = document.querySelector('.fc_fixed_menu'); 
    console.log(headersche);
    if( header != null){header.style.display = "none";}
    if( headersche != null){headersche.style.display = "none";}
    if( footer != null){footer.style.display = "none";}
    if( menu != null){menu.style.display = "none";}
    if( backlink != null){backlink.style.display = "none";}
    if( thummenu != null){
      thummenu.removeAttribute('style');
      thummenu.style.display = "none";
    }
}
  }, 10); 
  }
